# -*- coding: utf-8 -*-
P1 = "Cari kalimat yang menyatakan pendapat/alasan penulis (〜からだ、〜と思う、しかし〜)."
P2 = "Cocokkan setiap pilihan dengan teks; pilihan yang menambahkan hal yang tidak ada di teks adalah salah."
LN = 'Teks panjang (内容理解・長文)'
W = ['Tidak disebut dalam teks.', 'Tidak sesuai dengan isi teks.', 'Bertentangan dengan isi teks.']
def L(jp, idt, *qs): return dict(slot='cho', jenis=LN, jp=jp, id=idt, qs=[(q, o, a, al, bk, W, p) for (q, o, a, al, bk, p) in qs])
B = [
 L('最近、「シェアハウス」という住み方が若い人の間で人気を集めている。一つの家に複数の人が住み、台所や風呂を共同で使う。家賃が安く、一人暮らしより費用を抑えられるのが一番の理由だ。\nさらに、住人同士で食事を作ったり、休日に一緒に出かけたりするなど、人とのつながりが生まれる点も魅力だという。一人暮らしでは孤独を感じやすいが、シェアハウスでは相談できる相手が近くにいる。\nしかし、生活のリズムや価値観が違う人と暮らすため、トラブルが起きることも少なくない。例えば、掃除の分担や音の問題だ。このため、入居前にルールをしっかり決めておくことが大切だと、運営会社の人は話している。','Belakangan sharehouse populer di kalangan anak muda. Beberapa orang tinggal dalam satu rumah dan berbagi dapur dan kamar mandi. Alasan terbesar adalah sewa murah sehingga biaya lebih hemat daripada hidup sendiri. Selain itu hubungan antarpenghuni seperti memasak bersama atau bepergian saat libur juga jadi daya tarik. Hidup sendiri mudah merasa kesepian tapi di sharehouse ada orang untuk berkonsultasi. Namun karena irama hidup dan nilai berbeda, masalah tak jarang terjadi, misalnya pembagian bersih-bersih dan suara. Karena itu menetapkan aturan sebelum masuk penting, kata pihak pengelola.',
   ('シェアハウスが人気の一番の理由は何か。',['家賃が安く費用を抑えられるから','部屋が広いから','駅に近いから','家具が新しいから'],0,'Sewa murah.','家賃が安く、一人暮らしより費用を抑えられるのが一番の理由',P1),
   ('シェアハウスの魅力として挙げられているものはどれか。',['人とのつながりが生まれる','静かに暮らせる','掃除をしなくていい','ペットが飼える'],0,'Hubungan antarpenghuni.','人とのつながりが生まれる点も魅力',P2),
   ('運営会社の人は何が大切だと言っているか。',['入居前にルールをしっかり決めること','一人で暮らすこと','家賃を上げること','住人を減らすこと'],0,'Menetapkan aturan.','入居前にルールをしっかり決めておくことが大切',P2)),
 L('私は去年、地元の町を離れて、東京で働き始めた。最初の数か月は、毎日が驚きの連続だった。人が多く、電車は混み、同じ建物に住んでいても隣人の顔さえ知らない。故郷とはまったく違う世界だった。\nそんなとき、同じ会社の先輩が声をかけてくれた。「無理に慣れようとしなくていい。ゆっくり自分のペースで過ごせばいい」。その一言で、私は肩の力が抜けた。\nそれから、私は休日に近所を散歩し、小さな喫茶店を見つけて通うようになった。店主と少しずつ話すようになり、気がつくと、東京にも自分の居場所ができていた。新しい環境に慣れるには、焦らず小さな一歩を重ねることが大切だと、今は思う。','Tahun lalu saya meninggalkan kota asal dan mulai bekerja di Tokyo. Beberapa bulan pertama tiap hari penuh kejutan. Orang banyak, kereta penuh, bahkan tak kenal wajah tetangga satu gedung. Dunia yang sama sekali berbeda dari kampung. Saat itu senior sekantor menyapa saya. Katanya tak perlu memaksakan diri terbiasa, jalani dengan kecepatan sendiri. Dengan ucapan itu bahu saya melemas. Sejak itu saya jalan-jalan di sekitar saat libur, menemukan kafe kecil dan rutin ke sana. Sedikit demi sedikit bicara dengan pemiliknya dan tanpa sadar di Tokyo pun ada tempat saya. Untuk terbiasa dengan lingkungan baru penting menumpuk langkah kecil tanpa terburu-buru.',
   ('東京に来た最初のころ、「私」はどうだったか。',['驚きの連続だった','すぐに慣れた','毎日が楽しかった','友達がたくさんできた'],0,'Penuh kejutan.','毎日が驚きの連続だった',P1),
   ('先輩の言葉を聞いて、「私」はどうなったか。',['肩の力が抜けた','会社を辞めたくなった','焦りが強まった','東京が嫌いになった'],0,'Bahu melemas.','肩の力が抜けた',P2),
   ('「私」が大切だと思っていることは何か。',['焦らず小さな一歩を重ねること','早く慣れること','故郷に帰ること','人と話さないこと'],0,'Menumpuk langkah kecil.','焦らず小さな一歩を重ねること',P2)),
 L('日本の企業では、これまで「年功序列」が広く行われてきた。年齢や勤続年数が長いほど、給料や地位が上がる制度だ。この制度には、社員が安心して長く働けるという利点がある。\nしかし、近年は能力や成果を重視する企業が増えている。若くても成果を出せば、高い給料や重要な仕事を任される。このため、若手のやる気が高まるという声がある。\n一方で、成果ばかりを求めると、同僚と協力する意識が弱くなる恐れもある。実際、競争が厳しすぎて、職場の雰囲気が悪くなったという例もある。どちらの制度にも長所と短所があり、会社の状況に合わせて、両方のよい点を取り入れる工夫が求められている。','Di perusahaan Jepang selama ini nenkou joretsu (senioritas) meluas: makin tua atau lama bekerja makin naik gaji dan posisi. Sistem ini punya keuntungan karyawan tenang bekerja lama. Namun belakangan makin banyak perusahaan menekankan kemampuan dan hasil. Walau muda bila berprestasi mendapat gaji tinggi dan tugas penting, sehingga motivasi anak muda naik. Di sisi lain jika hanya menuntut hasil, kesadaran bekerja sama dengan rekan bisa melemah. Ada contoh suasana kerja memburuk karena persaingan terlalu keras. Kedua sistem punya kelebihan dan kekurangan, dan dibutuhkan upaya menggabungkan sisi baik keduanya sesuai kondisi perusahaan.',
   ('年功序列の利点は何か。',['社員が安心して長く働ける','若い人が早く出世できる','給料が必ず高くなる','競争が激しくなる'],0,'Karyawan tenang bekerja lama.','社員が安心して長く働けるという利点',P1),
   ('成果を重視する制度の問題点として挙げられているものはどれか。',['協力する意識が弱くなる恐れがある','給料が下がる','仕事が少なくなる','年齢が関係なくなる'],0,'Kerja sama bisa melemah.','協力する意識が弱くなる恐れもある',P2),
   ('筆者はどうすることが求められていると考えているか。',['両方のよい点を取り入れる工夫','年功序列だけにする','成果主義だけにする','制度をなくす'],0,'Menggabungkan sisi baik keduanya.','両方のよい点を取り入れる工夫',P2)),
 L('私の町の駅には、毎朝七時になると、同じ時間に必ず現れるおじいさんがいる。おじいさんは、改札の前に立って、通勤する人たちに「いってらっしゃい」と声をかけている。最初は、知らない人に声をかけられて、驚く人も多かったようだ。\nしかし、毎日続けるうちに、挨拶を返す人が増え、今では駅の朝の風景の一部になっている。私も、疲れていても、おじいさんの声を聞くと、不思議と元気が出る。\n先日、おじいさんに理由を聞いてみた。すると、「昔、自分も仕事に疲れていたとき、見知らぬ人の声かけに救われた。それを今度は自分がしたいと思った」と笑顔で教えてくれた。小さな親切は、巡り巡って、また誰かの力になるのだと感じた。','Di stasiun kota saya tiap pagi jam tujuh selalu muncul seorang kakek. Ia berdiri di depan gerbang dan menyapa para komuter dengan ucapan semoga hari baik. Awalnya banyak yang kaget disapa orang tak dikenal. Tapi seiring berlanjut, yang membalas sapaan bertambah dan kini jadi bagian pemandangan pagi stasiun. Saya pun walau lelah, mendengar suara kakek, anehnya jadi bersemangat. Beberapa hari lalu saya menanyakan alasan. Katanya dulu saat ia sendiri lelah bekerja, ia ditolong sapaan orang tak dikenal dan kali ini ia ingin melakukannya sendiri. Saya merasa kebaikan kecil berputar dan menjadi kekuatan bagi seseorang lagi.',
   ('おじいさんは毎朝何をしているか。',['駅で通勤する人に声をかけている','電車の掃除をしている','切符を売っている','道を案内している'],0,'Menyapa komuter.','通勤する人たちに「いってらっしゃい」と声をかけている',P1),
   ('おじいさんが声をかけ続ける理由は何か。',['昔、自分も見知らぬ人の声かけに救われたから','駅員の仕事だから','お金をもらっているから','暇だから'],0,'Dulu ia ditolong sapaan orang asing.','見知らぬ人の声かけに救われた',P2),
   ('「私」はこの話から何を感じたか。',['小さな親切は巡り巡って誰かの力になる','親切は無駄だ','朝は疲れる','知らない人と話すべきでない'],0,'Kebaikan kecil jadi kekuatan.','巡り巡って、また誰かの力になる',P2)),
 L('最近、スマートフォンのアプリで、外国語を勉強する人が増えている。時間や場所を選ばずに学べる点が大きな魅力だ。通勤電車の中や、昼休みなど、ほんの数分の空き時間でも、手軽に勉強できる。\n学習アプリの中には、ゲームのように楽しめる工夫がされたものも多い。問題に正解するとポイントがたまり、順位を友達と競うこともできる。そのため、飽きずに続けられるという人が多い。\nただし、アプリだけで外国語を話せるようになるのは難しいという意見もある。実際に人と会話する機会がなければ、読む力や聞く力はついても、話す力は伸びにくいからだ。アプリで基礎を身につけ、実際に話す練習を組み合わせることが理想的だと、語学教師は指摘している。','Belakangan makin banyak orang belajar bahasa asing lewat aplikasi ponsel. Daya tarik besar adalah bisa belajar tanpa memilih waktu dan tempat. Di kereta komuter atau jam makan siang, bahkan beberapa menit waktu luang bisa dipakai belajar dengan mudah. Banyak aplikasi yang dibuat menyenangkan seperti game: jawaban benar menambah poin dan peringkat bisa dibandingkan dengan teman. Karena itu banyak yang bisa terus tanpa bosan. Namun ada pendapat sulit bisa berbicara hanya dari aplikasi. Tanpa kesempatan bercakap dengan orang, kemampuan membaca dan mendengar naik tapi berbicara sulit berkembang. Guru bahasa menunjuk bahwa ideal menggabungkan dasar dari aplikasi dengan latihan bicara langsung.',
   ('アプリで勉強する大きな魅力は何か。',['時間や場所を選ばずに学べること','先生がいること','値段が高いこと','試験がないこと'],0,'Bisa belajar tanpa memilih waktu dan tempat.','時間や場所を選ばずに学べる点が大きな魅力',P1),
   ('アプリが続けやすい理由は何か。',['ゲームのように楽しめる工夫があるから','先生が毎日来るから','勉強しなくていいから','友達が来るから'],0,'Ada unsur seperti game.','ゲームのように楽しめる工夫',P2),
   ('語学教師は何が理想的だと言っているか。',['アプリと実際に話す練習を組み合わせること','アプリだけで勉強すること','話す練習だけをすること','アプリをやめること'],0,'Menggabungkan aplikasi dan latihan bicara.','アプリで基礎を身につけ、実際に話す練習を組み合わせる',P2)),
 L('日本では、毎年多くの食品が捨てられている。まだ食べられるのに捨てられる食品は「食品ロス」と呼ばれ、大きな問題になっている。その量は、国民一人が毎日おにぎり一個分を捨てている計算になるという。\n原因の一つは、賞味期限が近づいた食品が売れ残ることだ。また、家庭でも、買いすぎた食材を使い切れずに捨ててしまうことが多い。\nこうした問題を減らすため、最近は、売れ残りそうな食品を安く売るアプリや、余った料理を必要な人に届ける活動が広がっている。私たち一人ひとりも、買い物の前に冷蔵庫の中を確認する、食べ切れる量だけを買うといった、身近なことから始められるだろう。','Di Jepang tiap tahun banyak makanan terbuang. Makanan yang masih bisa dimakan tapi dibuang disebut food loss dan jadi masalah besar. Jumlahnya, kalau dihitung, tiap warga membuang setara satu onigiri setiap hari. Salah satu penyebabnya adalah makanan yang mendekati kedaluwarsa tak laku. Di rumah tangga pun sering terbuang bahan yang dibeli berlebihan dan tak habis dipakai. Untuk mengurangi, belakangan menyebar aplikasi yang menjual murah makanan hampir tak laku dan kegiatan menyalurkan masakan sisa kepada yang membutuhkan. Tiap orang bisa mulai dari hal dekat seperti memeriksa kulkas sebelum belanja dan membeli hanya yang bisa dihabiskan.',
   ('「食品ロス」とは何か。',['まだ食べられるのに捨てられる食品','腐った食品','輸入できない食品','高い食品'],0,'Makanan yang masih bisa dimakan tapi dibuang.','まだ食べられるのに捨てられる食品',P1),
   ('食品ロスの原因として挙げられているものはどれか。',['賞味期限が近い食品が売れ残ること','食品が足りないこと','店が少ないこと','料理が下手なこと'],0,'Makanan mendekati kedaluwarsa tak laku.','賞味期限が近づいた食品が売れ残る',P2),
   ('個人ができることとして述べられているものはどれか。',['買い物の前に冷蔵庫の中を確認する','外食を増やす','買いだめする','料理をやめる'],0,'Memeriksa kulkas sebelum belanja.','買い物の前に冷蔵庫の中を確認する',P2)),
 L('日本の夏の風物詩の一つに、「風鈴」がある。軒下につるすと、風に揺れて涼しい音を出す。実際に気温が下がるわけではないが、その音を聞くと、不思議と涼しく感じられる。\n風鈴は、もともとは、悪い病気を防ぐお守りとして使われていたと言われている。それがやがて、涼しさを楽しむ夏の道具として広まった。素材も、ガラスや鉄、陶器などさまざまで、それぞれ違った音色を持つ。\n最近は、住宅が密集し、音が迷惑になるという理由で、風鈴をつるさない家も増えている。しかし、その音を聞くと、子どものころの夏を思い出して懐かしくなるという人も多い。季節を音で感じる文化を、これからも大切にしていきたい。','Salah satu ciri musim panas Jepang adalah furin (lonceng angin). Digantung di bawah atap, bergoyang tertiup angin dan mengeluarkan bunyi sejuk. Suhu sebenarnya tak turun tapi mendengar bunyinya terasa anehnya sejuk. Katanya furin awalnya dipakai sebagai jimat penangkal penyakit buruk. Lalu menyebar sebagai alat musim panas untuk menikmati kesejukan. Bahannya beragam seperti kaca, besi, dan tembikar dengan nada berbeda. Belakangan karena rumah rapat dan bunyi dianggap mengganggu makin banyak rumah tak menggantung furin. Tapi banyak juga yang mendengar bunyinya teringat musim panas masa kecil dan rindu. Budaya merasakan musim lewat bunyi ingin tetap dihargai.',
   ('風鈴の音を聞くとどう感じるか。',['不思議と涼しく感じる','暑く感じる','うるさく感じる','怖く感じる'],0,'Terasa sejuk.','不思議と涼しく感じられる',P1),
   ('風鈴はもともと何のために使われていたと言われているか。',['悪い病気を防ぐお守り','夏の飾り','音楽の楽器','天気を知る道具'],0,'Jimat penangkal penyakit.','悪い病気を防ぐお守り',P2),
   ('風鈴をつるさない家が増えている理由は何か。',['音が迷惑になると考えるから','値段が高いから','夏が短いから','風が弱いから'],0,'Bunyi dianggap mengganggu.','音が迷惑になるという理由',P2)),
 L('高校を卒業したあと、すぐに大学へ進学せず、一年間世界を旅した若者の話を聞いた。彼は、「勉強の前に、自分の目で世界を見てみたかった」と話す。アルバイトでお金をためて、十か国を回ったそうだ。\n旅の途中、言葉が通じなくて困ったり、お金を盗まれたりしたこともあったという。しかし、そのたびに、現地の人の優しさに助けられた。「人はどこでも助け合って生きているのだと実感した」と彼は言う。\n帰国後、彼は大学で国際関係を学び始めた。旅で感じた疑問をもとに、自分で学ぶべきテーマが見つかったからだ。回り道に見える経験も、あとで大きな意味を持つことがあるのだと、彼の話から教えられた。','Saya mendengar cerita seorang pemuda yang setelah lulus SMA tak langsung kuliah tapi berkeliling dunia setahun. Katanya sebelum belajar ia ingin melihat dunia dengan mata sendiri. Ia menabung dari kerja paruh waktu dan mengunjungi sepuluh negara. Di perjalanan ia kesulitan karena bahasa tak terpahami dan pernah dicuri uangnya. Tapi tiap kali ia ditolong kebaikan orang setempat. Katanya ia merasakan bahwa manusia di mana pun hidup saling menolong. Setelah pulang ia mulai belajar hubungan internasional di universitas karena menemukan tema yang harus dipelajari dari pertanyaan yang ia rasakan selama perjalanan. Dari ceritanya saya belajar bahwa pengalaman yang tampak jalan memutar bisa bermakna besar.',
   ('若者はなぜ旅に出たのか。',['勉強の前に自分の目で世界を見たかったから','大学に落ちたから','仕事が見つからなかったから','親に言われたから'],0,'Ingin melihat dunia sebelum belajar.','勉強の前に、自分の目で世界を見てみたかった',P1),
   ('旅の途中で若者が実感したことは何か。',['人はどこでも助け合って生きている','外国は危険だ','言葉が一番大切だ','お金がすべてだ'],0,'Manusia saling menolong.','人はどこでも助け合って生きている',P2),
   ('若者が帰国後に始めたことは何か。',['大学で国際関係を学ぶこと','また旅に出ること','会社で働くこと','本を書くこと'],0,'Belajar hubungan internasional.','大学で国際関係を学び始めた',P2)),
 L('私が通う大学の近くに、小さな古本屋がある。店主は七十歳を過ぎたおじいさんで、毎日店の奥に座って本を読んでいる。店内は狭く、天井まで積まれた本の間を、体を横にして歩かなければならない。\n初めて店に入ったとき、私は一冊の古い詩集を手に取った。ページの間に、前の持ち主が書いたと思われる小さなメモが挟まっていた。「ありがとう、この詩に救われた」。顔も知らない誰かの気持ちが、本を通して伝わってくるようで、胸が熱くなった。\n電子書籍にはない、こうした偶然の出会いが古本屋の魅力だと思う。この店が長く続いてほしいと、心から願っている。','Dekat universitas saya ada toko buku bekas kecil. Pemiliknya kakek lebih dari tujuh puluh tahun yang tiap hari duduk di belakang toko membaca. Toko sempit dan harus berjalan miring di antara buku bertumpuk sampai langit-langit. Saat pertama masuk saya mengambil sebuah kumpulan puisi lama. Di antara halamannya terselip catatan kecil yang tampaknya ditulis pemilik sebelumnya, berbunyi terima kasih, puisi ini menyelamatkanku. Perasaan orang yang tak dikenal tersampaikan lewat buku dan dada saya hangat. Saya kira pertemuan kebetulan seperti ini, yang tak ada di e-book, adalah daya tarik toko buku bekas. Dari hati saya berharap toko ini bertahan lama.',
   ('店内の様子として正しいものはどれか。',['狭く、天井まで本が積まれている','広くて明るい','新しい本ばかりだ','本が少ない'],0,'Sempit dan buku bertumpuk.','天井まで積まれた本',P1),
   ('「私」が胸が熱くなったのはなぜか。',['本に挟まったメモから誰かの気持ちが伝わったから','詩が難しかったから','本が安かったから','店主に話しかけられたから'],0,'Perasaan orang tak dikenal tersampaikan lewat catatan.','誰かの気持ちが、本を通して伝わってくる',P2),
   ('「私」は古本屋の魅力は何だと考えているか。',['偶然の出会いがあること','本が安いこと','店主が優しいこと','駅に近いこと'],0,'Pertemuan kebetulan.','こうした偶然の出会いが古本屋の魅力',P2)),
]
